## `cache.ts`

```ts
import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL ?? "redis://localhost:6379");

const DEFAULT_TTL = 300;        // 5 min
const NEGATIVE_TTL = 30;        // cache "not found" briefly
const NULL_SENTINEL = "__null__";

// In-process single-flight: concurrent misses for same key share one loader call
const inflight = new Map<string, Promise<unknown>>();

function ttlWithJitter(base: number): number {
  // ±10% jitter avoids mass expiry at same instant
  const jitter = Math.floor(base * 0.1 * (Math.random() * 2 - 1));
  return base + jitter;
}

export async function getOrLoad<T>(
  key: string,
  loader: () => Promise<T | null>,
  ttl = DEFAULT_TTL
): Promise<T | null> {
  // 1. Try cache (fail open if Redis down)
  try {
    const hit = await redis.get(key);
    if (hit !== null) {
      return hit === NULL_SENTINEL ? null : (JSON.parse(hit) as T);
    }
  } catch (err) {
    console.warn("cache read failed, falling back to source", err);
    return loader();
  }

  // 2. Miss: dedupe concurrent loads
  const existing = inflight.get(key);
  if (existing) return existing as Promise<T | null>;

  const p = (async () => {
    try {
      const value = await loader();
      try {
        if (value === null) {
          await redis.set(key, NULL_SENTINEL, "EX", NEGATIVE_TTL);
        } else {
          await redis.set(key, JSON.stringify(value), "EX", ttlWithJitter(ttl));
        }
      } catch (err) {
        console.warn("cache write failed", err);
      }
      return value;
    } finally {
      inflight.delete(key);
    }
  })();

  inflight.set(key, p);
  return p;
}

export async function invalidate(...keys: string[]): Promise<void> {
  if (keys.length === 0) return;
  try {
    await redis.del(...keys);
  } catch (err) {
    console.warn("cache invalidate failed", err);
  }
}
```

## `userProfile.ts`

```ts
import express from "express";
import { getOrLoad, invalidate } from "./cache";
import { db } from "./db"; // your data layer

const CACHE_VERSION = "v1"; // bump when profile shape changes → old entries ignored
const profileKey = (id: string) => `user:profile:${CACHE_VERSION}:${id}`;

export interface UserProfile {
  id: string;
  name: string;
  avatarUrl: string | null;
  bio: string | null;
  updatedAt: string;
}

async function loadProfile(id: string): Promise<UserProfile | null> {
  return db.users.findPublicProfile(id); // returns null if not found
}

export const router = express.Router();

router.get("/users/:id/profile", async (req, res, next) => {
  try {
    const profile = await getOrLoad(profileKey(req.params.id), () =>
      loadProfile(req.params.id)
    );
    if (!profile) return res.status(404).json({ error: "not_found" });

    // Optional HTTP caching for clients/CDN
    res.set("Cache-Control", "private, max-age=60");
    res.set("ETag", `"${profile.id}-${profile.updatedAt}"`);
    if (req.headers["if-none-match"] === res.get("ETag")) {
      return res.status(304).end();
    }
    res.json(profile);
  } catch (err) {
    next(err);
  }
});

router.patch("/users/:id/profile", async (req, res, next) => {
  try {
    const updated = await db.users.updateProfile(req.params.id, req.body);
    // Write DB first, then delete cache (not set) → avoids racing stale writes
    await invalidate(profileKey(req.params.id));
    res.json(updated);
  } catch (err) {
    next(err);
  }
});
```

## Key decisions

- **Delete on write, not update** — two concurrent writers can't leave stale value in cache; next read repopulates from DB.
- **Fail open** — Redis outage → serves from DB, no 500s.
- **Single-flight** — hot profile expiring doesn't fire N DB queries. Per-process only; multi-instance stampede needs Redis lock (`SET key NX PX`) if load is heavy.
- **Negative cache** — stops repeated DB hits for nonexistent/scraped IDs. Short TTL so newly created users appear fast.
- **Versioned key** — schema change = bump `CACHE_VERSION`, no flush needed.
- **Only public fields cached** — keep private data (email, tokens) out of shared cache; if caching per-viewer responses, put viewer ID in key.

Remaining race: read loads old row → write + delete → read sets old value. Bounded by TTL. If unacceptable, use delayed double-delete or versioned writes (`updatedAt` compare).

